import base64
import PyInstaller.__main__
import os
import shutil


def icon():
    return b''
base64_image = icon()
directory = os.getcwd()
exe_folder = rf'{directory}/exe_folder'
temp = rf'{directory}/temp'
icon_file_name = rf'{temp}/nobody.ico'

exe_file_name = input("Enter Your Exe File Name EX: APP without exe .. :")
try:
    os.mkdir(exe_folder)
except Exception as e:
    pass
try:
    os.mkdir(temp)
except:
    pass

with open(icon_file_name, 'wb') as img:
    img.write(base64.decodebytes(base64_image))
img.close()

try:
    PyInstaller.__main__.run([
        'Run.py',
        f'-n={exe_file_name.strip()}',
        f'-i={icon_file_name}',
        '-F',
        '-y',
        '-c',
        f'--specpath={temp}',
        f'--distpath={exe_folder}',
        f'--workpath={temp}',
        '--log-level=WARN',
        '--clean',
    ])
    shutil.rmtree('temp')
    print(f"Your File is ready to use ... {exe_folder}/{exe_file_name}.exe")
except Exception as e:
    print(e)
